INSERT OR IGNORE INTO public_entries ("entry_id", "lemma", "document", "digest", "summary", "frequency_order", "built_at") VALUES ('6a178f26-d9fc-4299-9c8d-657b69f5520b', 'pet', '{"id":"6a178f26-d9fc-4299-9c8d-657b69f5520b","lemma":"pet","frequency":{"zipf":4.45,"rank":3256},"pronunciations":[{"ipa":"pet","accent":"us","review":{"fact_id":"4ab16b0b-7704-4944-b170-ab9b5978edef","confidence":1,"verdict":"pass"}},{"ipa":"pet","accent":"uk","review":{"fact_id":"898da615-518f-457e-8f4d-bd56b1fa5e0e","confidence":1,"verdict":"pass"}}],"variants":[],"syllables":["pet"],"morphology":{"parts":[{"form":"pet","role":"base"}],"review":{"fact_id":"e3fc78ff-38e4-42c8-8875-353946da697f","confidence":0.96,"verdict":"pass"}},"meanings":[{"pos":"noun","cefr":"A1","pronunciations":[],"forms":{"plural":[{"form":"pets","irregular":false}]},"senses":[{"id":"2014af70-ee42-4478-8785-61fccba82f79","gloss":"An animal kept for companionship or pleasure.","labels":[],"region":null,"rare":false,"translations":{"zh":["宠物"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"37489fa8-c735-46b8-9235-a8398db7aad1","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"We had a rabbit as a pet when I was a child.","translations":{"zh":"我小时候，我们养了一只兔子当宠物。"},"review":{"fact_id":"e025cce1-17b1-4d07-a892-935abcae3612","confidence":0.99,"verdict":"pass"}},{"text":"Cats can make wonderful pets.","translations":{"zh":"猫可以成为很好的宠物。"},"review":{"fact_id":"b3754f27-2a0a-466a-bb7e-29ef11dc368f","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"keep a pet","pattern":"verb_noun","review":{"fact_id":"adca267f-2df3-4d34-86ad-6ea51af887d1","confidence":0.99,"verdict":"pass"}},{"text":"family pet","pattern":"noun_noun","review":{"fact_id":"bb9f6c6d-9b71-421d-a437-d553bdc83da9","confidence":0.98,"verdict":"pass"}}],"topics":[{"id":"pets","name":{"en":"Pets","zh":"宠物"},"review":{"fact_id":"5db5650f-bdc7-41fc-a264-70571f611678","confidence":1,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[{"lemma":"animal","sense_id":"f816f9b8-4a89-4b2a-9cb2-424ff9c72a3f","gloss":"A living creature that is not a plant or a human, such as a dog, bird, fish or insect.","review":{"fact_id":"2e4c027e-1615-4790-a065-11b6cbae5e04","confidence":1,"verdict":"pass"}}],"narrower":[{"lemma":"lapdog","sense_id":"1fcdeb39-7fc8-4ec6-98d4-7b852593f5e9","gloss":"A small dog kept as a pet and suited to sitting on a person''s lap.","review":{"fact_id":"998884a5-ab37-4b77-985b-6d44d62cb4e7","confidence":0.99,"verdict":"pass"}},{"lemma":"dog","sense_id":"dffccb4e-a0b2-4d16-95ae-2489246ff947","gloss":"A domesticated animal with four legs, a tail, and a barking voice, often kept as a pet or trained for work.","review":{"fact_id":"7dc346c5-eabf-458e-8930-03d1cef8965c","confidence":1,"verdict":"pass"}},{"lemma":"cat","sense_id":"af217c59-c334-4cec-b4a4-2bcf923341d4","gloss":"A small domesticated animal with soft fur, whiskers, and retractable claws, often kept as a pet.","review":{"fact_id":"6a6c7f60-8d38-41e0-9597-a09842b32ed1","confidence":1,"verdict":"pass"}},{"lemma":"rabbit","sense_id":"d638f02f-7380-41c5-89b5-f884ef10176c","gloss":"A small animal with long ears, soft fur, and a short tail that lives in burrows.","review":{"fact_id":"fd02ef5f-30d6-4df4-9565-82fddeac9426","confidence":1,"verdict":"pass"}},{"lemma":"hamster","sense_id":"8dde5320-228c-4a4f-83fd-ab2a611e128d","gloss":"A small animal like a mouse, with soft fur and no tail, often kept as a pet.","review":{"fact_id":"6631463f-e7f5-441a-b0e0-b9ea75599cd1","confidence":1,"verdict":"pass"}},{"lemma":"guinea pig","sense_id":"701452fa-1e1e-4956-b69e-5393b68404d1","gloss":"A small animal with short ears and no tail, often kept as a pet.","review":{"fact_id":"9b2e2faa-5dea-42ff-93f4-8cf4187365e8","confidence":1,"verdict":"pass"}},{"lemma":"parrot","sense_id":"4509a88f-a110-49be-a2d0-8195ed3105da","gloss":"A tropical bird with a curved beak and brightly coloured feathers, some kinds of which can copy human speech.","review":{"fact_id":"e28ecd13-3783-4ef4-a8bd-90e8f1ac8310","confidence":1,"verdict":"pass"}},{"lemma":"budgie","sense_id":"e8ef3a10-a35a-489c-86cc-cb516b72587c","gloss":"A small brightly coloured bird of the parrot family, often kept as a pet in a cage.","review":{"fact_id":"0663d13f-c147-438c-ae5e-df971fce4d54","confidence":1,"verdict":"pass"}},{"lemma":"canary","sense_id":"add45aa5-247c-49c3-9953-a211cf5e5614","gloss":"A small yellow bird that is known for its singing and is often kept as a pet.","review":{"fact_id":"fbfc125f-0c95-4bb3-a128-f1d74984fd9d","confidence":1,"verdict":"pass"}},{"lemma":"goldfish","sense_id":"c7c3b617-731b-40be-9b4f-716b8c51682f","gloss":"A small orange fish, often kept as a pet in a bowl or pond.","review":{"fact_id":"b5559953-ee65-4594-b91f-2a77454d6af5","confidence":1,"verdict":"pass"}}],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"8c678797-beb7-4650-92ce-7d19a0cb6a36","confidence":0.99,"verdict":"pass"},"translations":{"zh":[{"fact_id":"c8a249ee-cc94-448a-bee1-82177973cb18","confidence":1,"verdict":"pass"}]}}},{"id":"a74e9392-cd26-436e-991e-33814959ba7d","gloss":"A person who receives special affection or preferential treatment from someone.","labels":[],"region":null,"rare":false,"translations":{"zh":["宠儿；受偏爱的人"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"d0cf16ee-03ac-428a-8368-a0fec7d62b57","confidence":0.93,"verdict":"pass"}},"examples":[{"text":"The other children teased him for being the teacher''s pet.","translations":{"zh":"其他孩子因为他是老师的宠儿而取笑他。"},"review":{"fact_id":"27daeced-3e3c-4dc5-ba5c-093a7e1a629c","confidence":0.99,"verdict":"pass"}},{"text":"Everyone in the office knows she''s the boss''s pet.","translations":{"zh":"办公室里人人都知道她是老板的宠儿。"},"review":{"fact_id":"f1be7f48-503a-4861-97f6-e3e15443c06f","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"teacher''s pet","pattern":"phrase","review":{"fact_id":"49413ff0-3b4f-4154-8d90-0e85b0352621","confidence":0.99,"verdict":"pass"}}],"topics":[{"id":"classroom","name":{"en":"In the classroom","zh":"课堂"},"review":{"fact_id":"710e812f-22a9-4d06-a9fb-bf5c7c7bd3d6","confidence":0.9,"verdict":"pass"}}],"relations":{"synonyms":[{"lemma":"favourite","sense_id":"0ac94283-4986-410d-894e-b082ca96ceef","gloss":"A person given special attention or better treatment by someone in authority.","review":{"fact_id":"f5e6119c-a31d-4d4b-9ff7-34155381e960","confidence":0.87,"verdict":"pass"}}],"antonyms":[],"broader":[],"narrower":[{"lemma":"teacher''s pet","sense_id":"6b5a3848-7f69-4fab-9e07-491446d03af4","gloss":"A pupil who receives preferential treatment from a teacher.","review":{"fact_id":"d06f8702-0035-4a47-a91e-87dc78c297bf","confidence":0.98,"verdict":"pass"}}],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"d16b247a-3805-4ae5-a882-d180a031fc4a","confidence":0.9,"verdict":"pass"},"translations":{"zh":[{"fact_id":"78b60343-b3aa-440c-af4c-9dc87b9d379b","confidence":0.99,"verdict":"pass"}]}}},{"id":"7808a552-6ef3-4f12-ae37-50a7936b08f7","gloss":"A kind or lovable person, especially one addressed affectionately.","labels":["informal"],"region":"british","rare":false,"translations":{"zh":["亲爱的；讨人喜欢的人"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"f063ac01-a484-4fa0-9510-69cb86a72a04","confidence":0.91,"verdict":"pass"}},"examples":[{"text":"Be a pet and bring me my glasses, would you?","translations":{"zh":"乖，帮我把眼镜拿来，好吗？"},"review":{"fact_id":"61953c16-99f7-4a01-9022-694a048fd7f5","confidence":0.97,"verdict":"pass"}},{"text":"You look tired, pet. Come and sit down.","translations":{"zh":"你看起来累了，亲爱的。过来坐下吧。"},"review":{"fact_id":"7f3034a5-8f5a-43c3-8d5f-2d6476b58586","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"be a pet","pattern":"phrase","review":{"fact_id":"6dbbe48b-5898-4db1-88a3-b50273b6fe9b","confidence":0.94,"verdict":"pass"}}],"topics":[{"id":"communication-styles","name":{"en":"Ways of communicating","zh":"沟通方式"},"review":{"fact_id":"94b52c76-cb0d-4a4e-954b-48e5971a77ae","confidence":0.88,"verdict":"pass"}}],"relations":{"synonyms":[{"lemma":"dear","sense_id":"289fa8fb-c252-4e8c-85f0-31f3a76ea6e6","gloss":"A kind or helpful person.","review":{"fact_id":"8e7635bf-5f10-4fe4-8ad5-a15e8f55695f","confidence":0.97,"verdict":"pass"}}],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"c659f0bf-1bf3-453a-a35b-03311c6bd8db","confidence":0.98,"verdict":"pass"},"translations":{"zh":[{"fact_id":"8be3370e-d814-42db-84bf-502cc55938ac","confidence":0.98,"verdict":"pass"}]}}}],"review":{"forms":{"plural":[{"fact_id":"3e6dbc55-0c15-41ff-ab33-6204ddb9c7e5","confidence":0.99,"verdict":"pass"}]}}},{"pos":"verb","cefr":null,"pronunciations":[],"forms":{"third_person_singular":[{"form":"pets","irregular":false}],"past":[{"form":"petted","irregular":false}],"past_participle":[{"form":"petted","irregular":false}],"present_participle":[{"form":"petting","irregular":false}]},"senses":[{"id":"fa1061e4-43ba-4d95-a56a-b6a5ae7795fd","gloss":"To stroke or touch an animal gently and affectionately.","labels":[],"region":null,"rare":false,"translations":{"zh":["（亲昵地）抚摸"]},"grammar":{"transitivity":"transitive","patterns":[],"prepositions":[],"review":{"fact_id":"f5787b2d-eed8-412e-95ff-289dc6db9ab6","confidence":0.99,"verdict":"pass"}},"examples":[{"text":"She knelt down to pet the dog.","translations":{"zh":"她跪下来抚摸那只狗。"},"review":{"fact_id":"3f63eecf-8908-43fc-8c45-10d7c39eafb1","confidence":0.99,"verdict":"pass"}},{"text":"Always ask the owner before you pet a strange dog.","translations":{"zh":"抚摸不熟悉的狗之前，一定要先征得主人的同意。"},"review":{"fact_id":"f15e949f-3c77-4da4-9861-77a72015288e","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"pet a dog","pattern":"verb_noun","review":{"fact_id":"8b5290f7-08d3-4694-8867-3a540a48f40b","confidence":0.94,"verdict":"pass"}}],"topics":[{"id":"pets","name":{"en":"Pets","zh":"宠物"},"revie