INSERT OR IGNORE INTO public_entries ("entry_id", "lemma", "document", "digest", "summary", "frequency_order", "built_at") VALUES ('9b4ed2f6-0aa9-4343-9b45-7f37741f78dd', 'dog', '{"id":"9b4ed2f6-0aa9-4343-9b45-7f37741f78dd","lemma":"dog","frequency":{"zipf":5.1,"rank":811},"pronunciations":[{"ipa":"dɒɡ","accent":"uk","review":{"fact_id":"8d8735a6-5ebf-4630-8fa1-8f006aac853f","confidence":0.99,"verdict":"pass"}},{"ipa":"dɔɡ","accent":"us","review":{"fact_id":"3b0fd46a-c756-438d-8cce-a18326991272","confidence":0.98,"verdict":"pass"}}],"variants":[],"syllables":["dog"],"morphology":{"parts":[{"form":"dog","role":"base"}],"review":{"fact_id":"76c44074-bc42-4c7e-8ef9-62f51e6bacd4","confidence":0.96,"verdict":"pass"}},"meanings":[{"pos":"noun","cefr":"A1","pronunciations":[],"forms":{"plural":[{"form":"dogs","irregular":false}]},"senses":[{"id":"dffccb4e-a0b2-4d16-95ae-2489246ff947","gloss":"A domesticated animal with four legs, a tail, and a barking voice, often kept as a pet or trained for work.","labels":[],"region":null,"rare":false,"translations":{"zh":["狗"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"f09c1880-3626-4217-8410-6bfc2dd0233d","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"The dog wagged its tail when it saw us.","translations":{"zh":"那只狗看到我们时摇起了尾巴。"},"review":{"fact_id":"9692d743-2e45-4c3a-a42f-aea62a1b1e6a","confidence":0.99,"verdict":"pass"}},{"text":"We take our dog for a walk every morning.","translations":{"zh":"我们每天早上都带狗出去散步。"},"review":{"fact_id":"e19af9b4-6156-46ac-8878-cd16823f7561","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"walk the dog","pattern":"verb_noun","review":{"fact_id":"cae1075e-a842-4219-8bc6-e75cb4b7b574","confidence":0.99,"verdict":"pass"}},{"text":"stray dog","pattern":"adjective_noun","review":{"fact_id":"1035d5c2-fefc-4657-81ee-3d772806aa20","confidence":0.99,"verdict":"pass"}},{"text":"guide dog","pattern":"noun_noun","review":{"fact_id":"c2f2ad80-56a3-4119-92b1-f66843d4302f","confidence":0.99,"verdict":"pass"}}],"topics":[{"id":"pets","name":{"en":"Pets","zh":"宠物"},"review":{"fact_id":"3cdd024c-d2d3-492b-8501-240c9ce34c50","confidence":1,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[{"lemma":"canine","sense_id":"94fee5d0-4e58-479c-85b9-2d5bade9b2f8","gloss":"An animal of the dog family, including dogs, wolves, and foxes.","domain":"biology","review":{"fact_id":"ab23c414-e6a6-4ad8-9176-5604cac21942","confidence":0.99,"verdict":"pass"}},{"lemma":"pet","sense_id":"2014af70-ee42-4478-8785-61fccba82f79","gloss":"An animal kept for companionship or pleasure.","review":{"fact_id":"7dc346c5-eabf-458e-8930-03d1cef8965c","confidence":1,"verdict":"pass"}},{"lemma":"animal","sense_id":"f816f9b8-4a89-4b2a-9cb2-424ff9c72a3f","gloss":"A living creature that is not a plant or a human, such as a dog, bird, fish or insect.","review":{"fact_id":"09dfbcab-e0fe-4a70-8ac2-323219524d24","confidence":1,"verdict":"pass"}},{"lemma":"mammal","sense_id":"cf81053e-3965-4afd-92e1-54dcdcd0e2f4","gloss":"A warm-blooded vertebrate animal whose females feed their young with milk and that typically has hair or fur.","review":{"fact_id":"b5f5521b-d218-467c-ab07-1afe1ba74548","confidence":1,"verdict":"pass"}}],"narrower":[{"lemma":"poodle","sense_id":"a1383ff5-20b3-4d01-b047-1064747fef29","gloss":"A dog of a breed with a dense curly coat, bred in several sizes.","review":{"fact_id":"13bb2095-52d5-498d-95dd-325817ff27bd","confidence":1,"verdict":"pass"}},{"lemma":"toy","sense_id":"ad727e46-b67c-4878-802c-4a3cb4cc572e","gloss":"A dog of a very small breed.","review":{"fact_id":"fba2b0c8-3bbe-4be5-8311-a268d0cf699a","confidence":1,"verdict":"pass"}},{"lemma":"puppy","sense_id":"dd6eda09-6769-4f9d-a757-dcf809461b63","gloss":"A young dog.","review":{"fact_id":"756b750e-3117-4bd0-a947-104daf93514d","confidence":1,"verdict":"pass"}}],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"a6d9af22-c533-4fc8-8967-ce949edbe546","confidence":0.99,"verdict":"pass"},"translations":{"zh":[{"fact_id":"d86f04ee-d470-488b-944f-46106c7e3174","confidence":1,"verdict":"pass"}]}}},{"id":"29ebf1fb-d287-44f5-9481-a7cc2a3d451f","gloss":"A male dog or a male of a related animal such as a fox.","labels":[],"region":null,"rare":false,"translations":{"zh":["公狗；雄性犬科动物"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"4554deb9-9824-422c-b273-394800a976a8","confidence":0.95,"verdict":"pass"}},"examples":[{"text":"Is your new puppy a dog or a bitch?","translations":{"zh":"你新养的小狗是公的还是母的？"},"review":{"fact_id":"51d21a62-8026-4ea8-927b-660dcfb21d87","confidence":0.99,"verdict":"pass"}},{"text":"The breeder keeps the dogs and bitches in separate kennels.","translations":{"zh":"繁育者把公狗和母狗养在不同的犬舍里。"},"review":{"fact_id":"1ac7c481-0bb2-4724-97d5-68d2a16c4438","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"stud dog","pattern":"noun_noun","review":{"fact_id":"623377ee-501d-4eec-bde2-decfdc11775c","confidence":0.97,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[],"antonyms":[],"broader":[{"lemma":"male","sense_id":"79ee1bbc-430b-44ad-a287-ce69c57783a4","gloss":"A male person or animal.","review":{"fact_id":"759592d0-01ad-4596-a2d2-70d94b2e0603","confidence":0.99,"verdict":"pass"}},{"lemma":"canine","sense_id":"94fee5d0-4e58-479c-85b9-2d5bade9b2f8","gloss":"An animal of the dog family, including dogs, wolves, and foxes.","domain":"biology","review":{"fact_id":"31171d3a-72e4-431f-ade4-8149ad829449","confidence":0.96,"verdict":"pass"}}],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"6ea5eef5-2db6-4213-81e2-264363c51a50","confidence":0.99,"verdict":"pass"},"translations":{"zh":[{"fact_id":"9c28cb5c-9e27-41cc-b701-e86c074270e7","confidence":0.99,"verdict":"pass"}]}}},{"id":"019f3880-da23-4b2e-bdd6-035326f6885d","gloss":"A man described in a familiar or affectionate way as having a particular quality.","labels":["informal"],"region":null,"rare":false,"translations":{"zh":["家伙（对男子的亲昵称呼）"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"17230db7-44ff-485b-ab0d-3a665d266d72","confidence":0.9,"verdict":"pass"}},"examples":[{"text":"You lucky dog! I wish I could go on holiday too.","translations":{"zh":"你这个幸运的家伙！我也希望能去度假。"},"review":{"fact_id":"3a881793-8b60-44be-9eed-6cdd8c9ce7c2","confidence":0.99,"verdict":"pass"}},{"text":"He''s a sly old dog, but I like him.","translations":{"zh":"他是个狡猾的老家伙，不过我喜欢他。"},"review":{"fact_id":"cebb3f21-e4fd-4623-a646-6faa9f29b5c8","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"lucky dog","pattern":"adjective_noun","review":{"fact_id":"ea1a272b-4108-40b6-be6f-9dd22a8dfb49","confidence":0.99,"verdict":"pass"}},{"text":"sly old dog","pattern":"adjective_noun","review":{"fact_id":"250b1c0a-108a-44c9-a2ac-7d6058d1ddca","confidence":0.98,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[{"lemma":"fellow","sense_id":"3eba2815-b669-41c4-be7d-aec11aff587c","gloss":"A man referred to in a familiar or informal way.","review":{"fact_id":"04a3779c-64b5-416e-80bf-7b2ad4d965e8","confidence":0.97,"verdict":"pass"}}],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"43da1cee-9391-4655-94eb-7d711fec5ab9","confidence":0.96,"verdict":"pass"},"translations":{"zh":[{"fact_id":"9354213c-7018-46b7-a964-80048f52ac78","confidence":0.99,"verdict":"pass"}]}}},{"id":"18a43355-471e-45de-8c26-5f0e4fc635ea","gloss":"A person, especially a man, regarded as unpleasant or contemptible.","labels":["informal"],"region":null,"rare":false,"translations":{"zh":["卑鄙小人；无赖"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"1f7627f8-c883-4750-9792-c854bc2a5928","confidence":0.93,"verdict":"pass"}},"examples":[{"text":"You dirty dog! You knew she was married.","translations":{"zh":"你这个卑鄙的家伙！你明明知道她已经结婚了。"},"review":{"fact_id":"7685c9b9-dd02-4bec-b229-c0069fe45866","confidence":0.99,"verdict":"pass"}},{"text":"That lying dog stole money from his own mother.","translations":{"zh":"那个满嘴谎话的无赖竟然偷自己母亲的钱。"},"review":{"fact_id":"51380731-f5e9-4fcb-9739-807b3898599b","confidence":0.98,"verdict":"pass"}}],"collocations":[{"text":"dirty dog","pattern":"adjective_noun","review":{"fact_id":"362ed66d-4e78-42a2-a187-13a3eff8192b","confidence":0.98,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[{"lemma":"cur","sense_id":"f3d13d04-60ad-455b-9b7d-997bd82e7451","gloss":"A person regarded as unpleasant or contemptible.","review":{"fact_id":"87716bb9-2afb-4799-b2a5-92681ff275ff","confidence":0.89,"verdict":"pass"}}],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"f7ec280f-b933-4d5d-8a50-cf7d648c79f2","confidence":0.96,"verdict":"pass"},"translations":{"zh":[{"fact_id":"962b4530-f259-4893-8ab7-7c42b8b2cfb1","confidence":0.99,"verdict":"pass"}]}}},{"id":"8242b453-1470-4de0-822b-ec49a97a212a","gloss":"Something of very poor quality or something that is a commercial failure.","labels":["informal"],"region":null,"rare":false,"translations":{"zh":["劣质品；失败之作"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"3080cf8b-bd9b-4cd2-bdcb-56d5b8563655","confidence":0.88,"verdict":"pass"}},"examples":[{"text":"The used car I bought turned out to be a dog.","translations":{"zh":"我买的那辆二手车结果是辆破车。"},"review":{"fact_id":"4bf9fb1c-870a-4f7b-8d48-aea90f198bbe","confidence":0.99,"verdict":"pass"}},{"text":"Their latest film was a real dog and lost millions at the box office.","translations":{"zh":"他们的最新电影是一部十足的烂片，票房亏损了数百万。"},"review":{"fact_id":"f30822aa-e00a-4caa-b39a-19cb2826e9f5","confidence":0.98,"verdict":"pass"}}],"collocations":[{"text":"a real dog","pattern":"adjective_noun","review":{"fact_id":"e74c0a61-5764-41da-a232-1c20d5b32c46","confidence":0.92,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[{"lemma":"dud","sense_id":"fddb9de9-641b-4ef1-8fc6-c1457e0f1925","gloss":"Something that fails to work properly or is unsuccessful.","review":{"fact_id":"476b6c94-967d-48b7-836d-23e00b463524","confidence":0.91,"verdict":"pass"}}],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"fcbb6173-7ab6-4381-a961-7ee12234b97a","confidence":0.92,"verdict":"pass"},"translations":{"zh":[{"fact_id":"83fc950e-6a6b-4492-b1b9-9e62e1f89a31","confidence":0.99,"verdict":"pass"}]}}},{"id":"7984c21b-e4b3-41f9-b200-2e40c166b569","gloss":"A woman considered physically unattractive.","labels":["offensive"],"region":null,"rare":false,"translations":{"zh":["丑女（侮辱性称呼）"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"cf08dab5-f4e3-4f8d-b1ce-38a87e8669b0","confidence":0.89,"verdict":"pass"}},"examples":[{"text":"Calling a woman a dog because you dislike her appearance is insulting.","translations":{"zh":"因为不喜欢一个女人的外貌就叫她“丑女”，是对她的侮辱。"},"review":{"fact_id":"5fb7b247-e681-47eb-8680-49e57f891081","confidence":0.96,"verdict":"pass"}},{"text":"He cruelly called her a dog because of her looks.","translations":{"zh":"他因为她的长相而刻薄地骂她是丑女。"},"review":{"fact_id":"81da25e0-d2bd-4729-8298-da4123bf27af","confidence":0.96,"verdict":"pass"}}],"collocations":[],"topics":[{"id":"appearance","name":{"en":"Appearance","zh":"外貌"},"review":{"fact_id":"11e1855b-7a13-42f7-b535-11e6497e98c6","confidence":0.96,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[],"broader":[{"lemma":"woman","sense_id":"03c88674-84b9-4dca-b276-5ceac03d2c13","gloss":"An adult female human being.","review":{"fact_id":"e91f436b-87d2-4a46-9c02-98508edc2757","confidence":0.99,"verdict":"pass"}}],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"4a9366a4-a0ec-4b54-a944-b868df0158ce","confidence":0.99,"verdict":"pass"},"translations":{"zh":[{"fact_id":"402aa1bb-fc44-4966-ad45-326add21708b","confidence":0.99,"verdict":"pass"}]}}},{"id":"d5f2f7ee-1237-4864-a9a6-fd33e4f3e725","gloss":"Greyhound racing, especially as an activity involving betting.","labels":["informal"],"region":"british","rare":false,"translations":{"zh":["赛狗（尤指下注的赛狗活动）"]},"grammar":{"number":"plural_only","article":"with_the","patterns":[],"prepositions":[],"review":{"fact_id":"4ae99572-19eb-4e99-8fc8-951c984348cf","confidence":0.97,"verdict":"pass"}},"examples":[{"text":"We spent an evening at the dogs and placed a few bets.","translations":{"zh":"我们在赛狗场玩了一个晚上，还下了几次注。"},"review":{"fact_id":"d9a44a5c-87f0-4b8b-8a6f-c8e2ee456c0f","confidence":0.99,"verdict":"pass"}},{"text":"My uncle used to go to the dogs every Friday night.","translations":{"zh":"我叔叔以前每周五晚上都去看赛狗。"},"review":{"fact_id":"9a3e293d-43ad-478b-85b6-85e8e2f13aae","confidence":0.98,"verdict":"pass"}}],"collocations":[{"text":"a night at the dogs","pattern":"phrase","review":{"fact_id":"ef0caffa-12c9-4977-ab09-2bf98f0a1a47","confidence":0.96,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[{"lemma":"greyhound racing","sense_id":"92e9283d-bdef-4769-a0dc-330cffcf5597","gloss":"The sport of racing greyhounds around a track, often involving betting on the results.","review":{"fact_id":"f6426ed0-0842-48f7-b58e-7a599785ab37","confidence":0.84,"verdict":"pass"}}],"antonyms":[],"broader":[{"lemma":"racing","sense_id":"8f8c8a71-1da0-4773-b780-6e18248dfbc3","gloss":"The sport of competing in contests of speed.","review":{"fact_id":"e58b0934-244c-4f74-9df7-940bd9f06ca5","confidence":0.99,"verdict":"pass"}}],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"3bde1654-82d5-4658-97c6-05452f4acc54","confidence":0.99,"verdict":"pass"},"translations":{"zh":[{"fact_id":"b28bf015-d86b-4908-88e1-c034597df8b7","confidence":0.99,"verdict":"pass"}]}}},{"id":"1ca80275-50d1-4ff0-b70c-0aad1530e2ce","gloss":"A hot dog.","labels":["informal"],"region":"american","rare":false,"translations":{"zh":["热狗"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"89884084-1839-49f3-b935-c2cb7f75ed49","confidence":0.94,"verdict":"pass"}},"examples":[{"text":"I''ll have a dog with mustard and a large soda.","translations":{"zh":"我要一个加芥末酱的热狗和一大杯汽水。"},"review":{"fact_id":"e7ee86ed-1f9d-4250-ae32-76d6dba0ca3f","confidence":0.99,"verdict":"pass"}},{"text":"We bought a couple of dogs at the baseball game.","translations":{"zh":"我们在棒球比赛现场买了两个热狗。"},"review":{"fact_id":"0d6635c4-a104-49a0-96c2-7b5852727c5f","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"chili dog","pattern":"noun_noun","review":{"fact_id":"57e66553-b69b-4dc1-8488-3b24c7de6238","confidence":0.99,"verdict":"pass"}}],"topics":[{"id":"restaurant-ordering","name":{"en":"At a restaurant","zh":"餐厅点餐"},"review":{"fact_id":"3e2680b8-6c11-416b-acb6-5fce091f68a5","confidence":0.9,"verdict":"pass"}}],"relations":{"synonyms":[{"lemma":"hot dog","sense_id":"13c15a76-8400-4a7c-a220-75d44c2abdcb","gloss":"A cooked frankfurter, especially one served in a split bread roll.","review":{"fact_id":"f20fbac1-5d59-47d2-a4ce-3f7e5c60cbc7","confidence":0.95,"verdict":"pass"}}],"antonyms":[],"broader":[{"lemma":"sausage","sense_id":"f1566e22-5dd2-4440-922b-dfc766aafa30","gloss":"A food consisting of finely chopped meat mixed with seasonings and enclosed in a thin casing.","review":{"fact_id":"44b20e64-8115-438a-bff6-1796a93b9e35","confidence":0.94,"verdict":"pass"}}],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"26979af8-f8f0-4307-b30a-d903b9e3a139","confidence":0.99,"verdict":"pass"},"translations":{"zh":[{"fact_id":"77183119-41c8-4f29-b478-b74570d11467","confidence":1,"verdict":"pass"}]}}},{"id":"86873f91-9809-47ec-a84c-f75652c56c07","gloss":"A person''s feet.","labels":["slang"],"region":"american","rare":false,"translations":{"zh":["双脚"]},"grammar":{"number":"plural_only","patterns":[],"prepositions":[],"review":{"fact_id":"0b627003-e40b-4f98-9daf-c7cd413ed56f","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"After walking all day, my dogs are barking.","translations":{"zh":"走了一整