INSERT OR IGNORE INTO public_entries ("entry_id", "lemma", "document", "digest", "summary", "frequency_order", "built_at") VALUES ('bb313d03-e221-465f-9bac-54677b966447', 'animal', '{"id":"bb313d03-e221-465f-9bac-54677b966447","lemma":"animal","frequency":{"zipf":4.81,"rank":1611},"pronunciations":[{"ipa":"ˈænɪməl","accent":"us","review":{"fact_id":"6758af98-1c07-4a16-a7d7-9d234e64fb00","confidence":0.98,"verdict":"pass"}},{"ipa":"ˈænɪməl","accent":"uk","review":{"fact_id":"76da71b8-c95c-47f1-ab32-02a741abf0a8","confidence":0.99,"verdict":"pass"}}],"variants":[],"syllables":["an","i","mal"],"morphology":{"parts":[{"form":"animal","role":"base"}],"review":{"fact_id":"83e70b3e-6ac6-4f77-972a-b135d3852c54","confidence":0.92,"verdict":"pass"}},"meanings":[{"pos":"noun","cefr":"A1","pronunciations":[],"forms":{"plural":[{"form":"animals","irregular":false}]},"senses":[{"id":"f816f9b8-4a89-4b2a-9cb2-424ff9c72a3f","gloss":"A living creature that is not a plant or a human, such as a dog, bird, fish or insect.","labels":[],"region":null,"rare":false,"translations":{"zh":["动物"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"4f500b21-15be-4ae4-bbdd-6db89ab0dd89","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"Please do not feed the animals at the zoo.","translations":{"zh":"请不要给动物园里的动物喂食。"},"review":{"fact_id":"65001cec-c599-4fc3-8b15-8a455de73946","confidence":1,"verdict":"pass"}},{"text":"The farm keeps animals such as cows, pigs, and sheep.","translations":{"zh":"这家农场饲养牛、猪、羊等动物。"},"review":{"fact_id":"5dc3420c-aa4b-459d-91da-a71a6419712f","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"wild animal","pattern":"adjective_noun","review":{"fact_id":"8c49a817-a0e3-434e-8100-0dfa60ab86ca","confidence":0.99,"verdict":"pass"}},{"text":"domestic animal","pattern":"adjective_noun","review":{"fact_id":"8c4e9746-351c-486e-9163-8c3d68bc9a56","confidence":0.99,"verdict":"pass"}},{"text":"farm animal","pattern":"noun_noun","review":{"fact_id":"46a688fc-1cb0-4bc9-9110-6ac90088cfac","confidence":0.98,"verdict":"pass"}}],"topics":[{"id":"wild-animals","name":{"en":"Wild animals","zh":"野生动物"},"review":{"fact_id":"1c1923ba-b5bb-4c49-b679-bad80dae3f8b","confidence":0.98,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[{"lemma":"human","sense_id":"7098366c-eab1-4fc0-80ac-9ed11389712e","gloss":"A person, considered as a member of the species to which all people belong.","review":{"fact_id":"3425ed9d-d877-40e9-b3fe-55f618bed781","confidence":1,"verdict":"pass"}}],"broader":[{"lemma":"creature","sense_id":"b27a4c22-8ffb-4be7-8f4f-3dc845cd49b3","gloss":"A living being, especially an animal.","review":{"fact_id":"c57b6c9a-2298-4414-8ebb-0435e5157daf","confidence":1,"verdict":"pass"}}],"narrower":[{"lemma":"bird","sense_id":"03bfbc15-e191-42e0-a2d7-de49f4207316","gloss":"An animal with feathers, wings, and a beak that lays eggs and is usually able to fly.","review":{"fact_id":"6b1377a1-7482-4cd1-a8fc-20fd1a577794","confidence":1,"verdict":"pass"}},{"lemma":"fish","sense_id":"e06e6007-6ca9-4e57-8416-f0c18438eba7","gloss":"An animal that lives in water, breathes through gills, and has fins.","review":{"fact_id":"4ed0c5c6-f2ba-487b-b162-fae3f468d67a","confidence":1,"verdict":"pass"}},{"lemma":"pet","sense_id":"2014af70-ee42-4478-8785-61fccba82f79","gloss":"An animal kept for companionship or pleasure.","review":{"fact_id":"2e4c027e-1615-4790-a065-11b6cbae5e04","confidence":1,"verdict":"pass"}},{"lemma":"giraffe","sense_id":"aadbf4ea-c652-4c93-86ce-79e87cc97b6f","gloss":"A very tall African animal with a very long neck, long legs, and dark patches on its coat.","review":{"fact_id":"999f1071-0baa-4c21-8e7a-8ee6836bc285","confidence":1,"verdict":"pass"}},{"lemma":"dog","sense_id":"dffccb4e-a0b2-4d16-95ae-2489246ff947","gloss":"A domesticated animal with four legs, a tail, and a barking voice, often kept as a pet or trained for work.","review":{"fact_id":"09dfbcab-e0fe-4a70-8ac2-323219524d24","confidence":1,"verdict":"pass"}},{"lemma":"cat","sense_id":"af217c59-c334-4cec-b4a4-2bcf923341d4","gloss":"A small domesticated animal with soft fur, whiskers, and retractable claws, often kept as a pet.","review":{"fact_id":"ba9ac27e-527e-4131-b3c2-4bb75b0a540e","confidence":1,"verdict":"pass"}},{"lemma":"cat","sense_id":"eef6d786-77bb-47fa-8c96-8a2c82c112b3","gloss":"A wild animal of the same family as the domestic cat, including lions, tigers, and leopards.","review":{"fact_id":"24d2ceba-ecb5-478f-bb5d-a99547bba224","confidence":1,"verdict":"pass"}},{"lemma":"horse","sense_id":"77d3bb8a-7f0f-40dc-9eb6-7d4346f8d454","gloss":"A large animal with four legs, a mane, and a long tail, used for riding, pulling loads, and racing.","review":{"fact_id":"782bb41e-09f0-4e7f-b8ea-d57dc2297ec3","confidence":1,"verdict":"pass"}},{"lemma":"cow","sense_id":"a32f313c-cf3f-4395-b421-35ad76b278de","gloss":"An adult female animal of the cattle family, kept for its milk or meat.","review":{"fact_id":"05c3b8bc-2de5-4c45-9209-b2c7cccceaba","confidence":1,"verdict":"pass"}},{"lemma":"pig","sense_id":"d7ef5ce7-fdd7-48fe-a452-e762342b95c0","gloss":"An animal with a broad snout, short legs, and a stout body, often kept on farms for its meat.","review":{"fact_id":"5f378d09-d73c-452a-be62-9c9452a07754","confidence":1,"verdict":"pass"}},{"lemma":"sheep","sense_id":"f8eb38c7-b16a-4807-bc7b-cdf8a1033c61","gloss":"A farm animal with a thick woolly coat, kept for its wool, meat, or milk.","review":{"fact_id":"aa851941-4fd1-44dd-8e5e-06f9011fc884","confidence":1,"verdict":"pass"}},{"lemma":"goat","sense_id":"8d45ad9e-6b69-4139-aeaa-de0e15561249","gloss":"An animal with hooves, horns, and a short tail, often kept for its milk, meat, or hair.","review":{"fact_id":"21b78280-d94d-4adb-879b-e34f933cd2c1","confidence":1,"verdict":"pass"}},{"lemma":"rabbit","sense_id":"d638f02f-7380-41c5-89b5-f884ef10176c","gloss":"A small animal with long ears, soft fur, and a short tail that lives in burrows.","review":{"fact_id":"a1f4e62f-15ad-43f0-9c5a-46f44c5cb36a","confidence":1,"verdict":"pass"}},{"lemma":"mouse","sense_id":"ff505306-a68e-4e1b-9b28-dcc5f8c0052a","gloss":"A small rodent with a pointed nose, rounded ears, and a long thin tail.","review":{"fact_id":"f57866d3-c971-4c4c-bf2a-fb0c481b48a7","confidence":1,"verdict":"pass"}},{"lemma":"rat","sense_id":"e2f23a8b-875f-4062-b659-e73b184e56ca","gloss":"A rodent resembling a large mouse, with a long, nearly hairless tail.","review":{"fact_id":"16facd6c-2769-4745-934d-d7bf890cb1be","confidence":1,"verdict":"pass"}},{"lemma":"lion","sense_id":"b93fc04b-b748-4f1a-b277-09c29d53edc1","gloss":"A large wild cat with a tawny coat, the male usually having a mane.","review":{"fact_id":"69fb6098-6ea5-43a3-ab83-b9209af226ec","confidence":1,"verdict":"pass"}},{"lemma":"tiger","sense_id":"6500c238-a7a0-4ebb-baf4-a478da825890","gloss":"A large wild cat native to Asia, with yellow-orange fur and black stripes.","review":{"fact_id":"7f34fe2a-9cac-4535-aa4c-3beb2dab1770","confidence":1,"verdict":"pass"}},{"lemma":"elephant","sense_id":"d1070518-402a-4a7c-a08f-303563701b41","gloss":"A very large animal with thick grey skin, a long trunk, and usually two long tusks.","review":{"fact_id":"043490db-376e-47b8-8ebf-f0884d7f6a7b","confidence":1,"verdict":"pass"}},{"lemma":"bear","sense_id":"394ac847-eb8c-40ca-93a2-c9914752db84","gloss":"A large, heavy wild mammal with thick fur, strong claws, and a short tail.","review":{"fact_id":"272071a1-fc0d-4c6a-8095-48283928797c","confidence":1,"verdict":"pass"}},{"lemma":"monkey","sense_id":"f48b8fa7-ad04-4cf8-996f-c6b919daf958","gloss":"A primate that usually has a long tail and lives in trees in warm countries.","review":{"fact_id":"02048782-f4a3-49f2-a73d-1cf35bd7400f","confidence":1,"verdict":"pass"}},{"lemma":"fox","sense_id":"9e713367-316f-4785-a261-7a1361815762","gloss":"A wild mammal of the dog family with a pointed muzzle and a bushy tail.","review":{"fact_id":"7454df71-1e95-4c24-a625-709e972fd5fb","confidence":1,"verdict":"pass"}},{"lemma":"bull","sense_id":"78069c40-c6d8-42fe-a998-80edfd2d8692","gloss":"An adult male animal of the cattle family.","review":{"fact_id":"81eaa500-f1b9-49d7-a872-19d102653792","confidence":1,"verdict":"pass"}},{"lemma":"chimpanzee","sense_id":"ed88a5cd-0524-4355-bdf4-0c7fc85b1fd5","gloss":"An African ape with dark hair, long arms, and no tail, closely related to humans.","review":{"fact_id":"d9daa1dc-342c-4901-806d-a1a50d3335a0","confidence":1,"verdict":"pass"}},{"lemma":"bat","sense_id":"94a92b80-87f9-4fda-a7b6-ba6bb5af9c40","gloss":"A small flying mammal with wings made of skin stretched between long finger bones.","review":{"fact_id":"d49a622e-a150-478e-9bb0-d9c224cd77b4","confidence":1,"verdict":"pass"}},{"lemma":"frog","sense_id":"0900ba51-e2a2-41e4-918c-ff2359bf5f02","gloss":"A small amphibian with smooth skin and long back legs used for jumping.","review":{"fact_id":"0e33ee07-7158-49a3-a916-24fefde8c544","confidence":1,"verdict":"pass"}},{"lemma":"snake","sense_id":"8b7e0949-fdee-4f7b-ab95-8b5711456c4f","gloss":"A reptile with a long body and no legs.","review":{"fact_id":"24e54224-c12b-4ce5-871b-89abf0427bb0","confidence":1,"verdict":"pass"}},{"lemma":"dinosaur","sense_id":"2b604e7f-1a7b-4e18-aa5a-70011c195a56","gloss":"One of a group of reptiles, many of them very large, that lived millions of years ago and are now extinct.","review":{"fact_id":"462e3578-d502-4341-904e-f923efd243b9","confidence":1,"verdict":"pass"}},{"lemma":"worm","sense_id":"bdb77858-96b3-444e-be8e-fc1bb67a26ee","gloss":"A small animal with a long, soft body and no legs that lives in soil, water, or other organisms.","review":{"fact_id":"227eb3e5-a3b5-4af7-be80-c4ea974b9b04","confidence":1,"verdict":"pass"}},{"lemma":"insect","sense_id":"ffe5e7fc-701f-450e-9941-227fdbfdc914","gloss":"A small animal with six legs, a body divided into head, thorax, and abdomen, and usually one or two pairs of wings.","review":{"fact_id":"d44f50b4-3404-4e40-bd2a-7e63f93738b8","confidence":1,"verdict":"pass"}},{"lemma":"mammal","sense_id":"cf81053e-3965-4afd-92e1-54dcdcd0e2f4","gloss":"A warm-blooded vertebrate animal whose females feed their young with milk and that typically has hair or fur.","review":{"fact_id":"4413c15f-c610-433d-9551-8b28f49a942f","confidence":1,"verdict":"pass"}},{"lemma":"reptile","sense_id":"a4b9d4da-4f1f-441f-9e69-e408db17c038","gloss":"A cold-blooded vertebrate with scaly skin that breathes air.","review":{"fact_id":"c42748f1-b2e8-489b-a882-458351ccfd66","confidence":1,"verdict":"pass"}},{"lemma":"zebra","sense_id":"db1ce321-d3ae-427c-bcfb-b57b1dfeff96","gloss":"An African wild animal like a horse, with black and white stripes on its body.","review":{"fact_id":"2a400a85-9e1c-41e2-b508-e0f4b6388653","confidence":1,"verdict":"pass"}},{"lemma":"kangaroo","sense_id":"6927687c-05c3-430c-8806-eb2f9fca9a6d","gloss":"A large Australian animal with a long tail and strong back legs that moves by jumping and carries its young in a pouch.","review":{"fact_id":"4136a63f-fae6-4693-9119-3adcb588cfd4","confidence":1,"verdict":"pass"}},{"lemma":"wolf","sense_id":"61c014f4-6123-4d56-a89b-60ab27ebe5d6","gloss":"A wild animal of the dog family that lives and hunts in groups.","review":{"fact_id":"df13bda4-06a9-48e8-be96-53439a106611","confidence":1,"verdict":"pass"}},{"lemma":"deer","sense_id":"8739dff9-87d1-456e-9ba1-a2b45088e2db","gloss":"A large wild animal that eats grass and leaves, the male of which usually has antlers.","review":{"fact_id":"7fa43e10-5213-497d-98cb-f5d7de8772c5","confidence":1,"verdict":"pass"}},{"lemma":"camel","sense_id":"e5e85e23-ec8e-4f3d-9b70-c0ea991c5357","gloss":"A large animal with a long neck and one or two humps on its back, used in the desert for carrying goods and people.","review":{"fact_id":"98db838f-db9f-4a91-abe1-95665e858e3d","confidence":1,"verdict":"pass"}},{"lemma":"donkey","sense_id":"1dd6653b-b148-4e94-9997-348b698b33fc","gloss":"An animal like a small horse with long ears, used for carrying loads.","review":{"fact_id":"a3d63901-0160-4363-8c69-26095133def4","confidence":1,"verdict":"pass"}},{"lemma":"hippopotamus","sense_id":"72235f70-99b5-4e8f-b8e1-2081591f8cbd","gloss":"A very large, heavy African animal with thick skin and short legs that lives in and near rivers.","review":{"fact_id":"514c32ba-fb93-4626-a6d7-2b4ffdf15c60","confidence":1,"verdict":"pass"}},{"lemma":"hippo","sense_id":"438d4bfc-351a-4d55-9e44-dd928cc0acf9","gloss":"A hippopotamus.","review":{"fact_id":"fd733936-2bcd-4f05-b74c-514dc92e1ed1","confidence":1,"verdict":"pass"}},{"lemma":"rhinoceros","sense_id":"17359cce-b190-4ce4-8bab-b2a3159632b0","gloss":"A large, heavy animal with thick skin and one or two horns on its nose, found in Africa and Asia.","review":{"fact_id":"f88c247f-76d5-494a-b43c-9161733d136c","confidence":1,"verdict":"pass"}},{"lemma":"rhino","sense_id":"27aefd2e-969f-4671-a097-f730f0da346f","gloss":"A rhinoceros.","review":{"fact_id":"a397dc08-e41f-4cd0-8519-d014dd6bb424","confidence":1,"verdict":"pass"}},{"lemma":"leopard","sense_id":"f7be81f7-5cc0-4721-a0a6-5242cb2905be","gloss":"A large wild animal of the cat family with yellowish fur and black spots, found in Africa and southern Asia.","review":{"fact_id":"7519b824-3d54-4880-9dd1-3f97b4a7bbbd","confidence":1,"verdict":"pass"}},{"lemma":"cheetah","sense_id":"60e0c478-ab77-4c0e-9b97-4aeb097c0a60","gloss":"A wild animal of the cat family with black spots, which can run very fast.","review":{"fact_id":"e586108e-67a9-44e0-b7ba-51bc058300bd","confidence":1,"verdict":"pass"}},{"lemma":"gorilla","sense_id":"f8780be2-cea4-4ea2-985b-4d72a7c112c5","gloss":"A very large, powerful African ape with black or brown hair.","review":{"fact_id":"fc527ece-c6b2-458b-afb9-84c24834c066","confidence":1,"verdict":"pass"}},{"lemma":"squirrel","sense_id":"aba0d0f9-dc2b-4996-a178-cebd03d3b151","gloss":"A small animal with a long thick tail and red, grey, or black fur that lives in trees and eats nuts.","review":{"fact_id":"deec66a0-50f9-423e-8c85-c03f59f73d39","confidence":1,"verdict":"pass"}},{"lemma":"hamster","sense_id":"8dde5320-228c-4a4f-83fd-ab2a611e128d","gloss":"A small animal like a mouse, with soft fur and no tail, often kept as a pet.","review":{"fact_id":"07e58b4c-72d8-4428-a128-de8b6fb64f62","confidence":1,"verdict":"pass"}},{"lemma":"guinea pig","sense_id":"701452fa-1e1e-4956-b69e-5393b68404d1","gloss":"A small animal with short ears and no tail, often kept as a pet.","review":{"fact_id":"6a339394-6992-4143-9010-c506736627c9","confidence":1,"verdict":"pass"}},{"lemma":"hedgehog","sense_id":"5549b436-1c08-4920-a3a5-a1d078d3f672","gloss":"A small animal with stiff sharp spines on its back that can roll into a ball to protect itself.","review":{"fact_id":"6c5d35b7-c8b4-45ec-8b6a-c83b04bc193c","confidence":1,"verdict":"pass"}},{"lemma":"whale","sense_id":"10ab1c57-d375-48aa-bade-fe6f5431504c","gloss":"A very large animal that lives in the sea and breathes air through an opening on the top of its head.","review":{"fact_id":"c221b24f-51c6-4481-b875-3ab9766d93f8","confidence":1,"verdict":"pass"}},{"lemma":"dolphin","sense_id":"2c19e029-0ba0-4a3d-9e5e-1558acd3d62b","gloss":"An intelligent sea animal like a large fish with a long pointed mouth.","review":{"fact_id":"42a3f19c-ba99-49f0-a755-7db54af2a53f","confidence":1,"verdict":"pass"}},{"lemma":"seal","sense_id":"4f2e769a-0321-4176-8212-92e8694d7ce4","gloss":"A sea animal with thick fur, flippers, and a smooth body that eats fish and lives near the coast.","review":{"fact_id":"944d9e4a-f832-4420-8133-de98406d321f","confidence":1,"verdict":"pass"}},{"lemma":"otter","sense_id":"8c86e720-11b5-4bda-baee-8238d61cac2a","gloss":"A small animal with thick brown fur, short legs, and webbed feet that lives in or near rivers and eats fish.","review":{"fact_id":"2568654d-b8ef-48f8-877c-7362670d467e","confidence":1,"verdict":"pass"}},{"lemma":"panda","sense_id":"ec024649-ad1c-426d-b1f4-1a4f92a7d1c5","gloss":"A large black and white animal like a bear that lives in China and eats bamboo.","review":{"fact_id":"19738ce7-6356-49f5-a466-92ac885377b2","confidence":1,"verdict":"pass"}},{"lemma":"koala","sense_id":"744fe917-424a-4ce5-816b-07ab2dd072fa","gloss":"An Australian animal with thick grey fur and large ears that lives in trees and eats leaves.","review":{"fact_id":"83a807f8-714a-4086-b871-b0201bdf72fa","confidence":1,"verdict":"pass"}},{"lemma":"toad","sense_id":"4a15452a-2432-4be7-8afa-a95897dd4711","gloss":"A small animal like a frog but with drier, rougher skin, that lives on land but breeds in water.","review":{"fact_id":"62f773f2-6c96-451d-8d26-ade45c884728","confidence":1,"verdict":"pass"}},{"lemma":"lizard","sense_id":"ba7a87ec-e1d7-4578-9b30-b9ed531de368","gloss":"A small animal with a long body, four short legs, a long tail, and rough skin.","review":{"fact_id":"c27b6b8f-6055-4f8b-b68f-08813e7d4598","confidence":1,"verdict":"pass"}},{"lemma":"crocodile","sense_id":"51738211-1e79-4d1a-a356-11f4a4b8c720","gloss":"A large animal with a long body, a long mouth, sharp teeth, and hard skin that lives in rivers in hot countries.","review":{"fact_id":"fd4f052e-2a4e-412f-b265-ed11d3a9a93c","confidence":1,"verdict":"pass"}},{"lemma":"alligator","sense_id":"a96b642e-d91c-4b5b-aee7-4e1216fe730b","gloss":"A large animal like a crocodile with a shorter, wider mouth, found in America and China.","review":{"fact_id":"6fab8c01-907a-4107-8a47-fdea21f6b3f4","confidence":1,"verdict":"pass"}},{"lemma":"turtle","sense_id":"c65f9b10-b28a-4df6-b15a-ad218e2e9d80","gloss":"An animal with a hard round shell that lives mainly in the sea.","review":{"fact_id":"849477c5-10a7-43d2-b7b9-02d6d158d751","confidence":1,"verdict":"pass"}},{"lemma":"tortoise","sense_id":"c8a80317-866d-472b-92e2-19a7881017cf","gloss":"A slow animal with a hard round shell into which it can pull its head and legs, living on land.","review":{"fact_id":"0b950204-4d46-44eb-bc4d-d2dfd0cd74a0","confidence":1,"verdict":"pass"}},{"lemma":"calf","sense_id":"363dba5e-33c1-466e-9229-f4c447767ad5","gloss":"A young cow.","review":{"fact_id":"7a307cb7-d5ba-4b4b-a6df-580138def9dd","confidence":1,"verdict":"pass"}},{"lemma":"ox","sense_id":"5cdfb0b0-3572-45c5-85c9-a43f2b7199d1","gloss":"A bull that has been castrated, used for pulling loads or for its meat.","review":{"fact_id":"b15d7726-5591-4cfd-86a1-fc8d4823f22c","confidence":1,"verdict":"pass"}},{"lemma":"beaver","sense_id":"baec3a29-14dd-49ef-8b27-bb23f1c75472","gloss":"An animal with a wide flat tail and strong teeth that lives in water and on land and builds dams across rivers.","review":{"fact_id":"f446db54-9750-48a9-98b3-3f122adf7cfd","confidence":1,"verdict":"pass"}},{"lemma":"badger","sense_id":"b5690afe-ad58-4d58-95e4-bbba9fe911a6","gloss":"An animal with grey fur and a black and white head that lives underground and comes out at night.","review":{"fact_id":"2c9fb784-a712-4b74-bb8b-30b5c72f917c","confidence":1,"verdict":"pass"}},{"lemma":"buffalo","sense_id":"c2e80422-6cce-4caa-9a08-8f5cfa5be800","gloss":"A large animal of the cow family with long curved horns, found in Africa and Asia.","review":{"fact_id":"e2fa0650-89ab-4606-b844-b78f4a038b86","confidence":1,"verdict":"pass"}},{"lemma":"moose","sense_id":"4e78c7c0-93fa-4a56-ae07-14f706e60c7f","gloss":"A large deer with very large flat antlers, found in North America, northern Europe, and Asia.","review":{"fact_id":"5d0a8e59-c398-4e2f-bc96-7c2376ce0db7","confidence":1,"verdict":"pass"}},{"lemma":"hare","sense_id":"1e5c0f18-27af-414c-858f-f93f9fe54006","gloss":"An animal like a large rabbit with long ears and long back legs that can run very fast.","review":{"fact_id":"91f3ef21-eb19-4a1a-b028-7fb468027900","confidence":1,"verdict":"pass"}},{"lemma":"raccoon","sense_id":"586ed369-7bff-4cab-8473-a3d92fcb1ca1","gloss":"A small North American animal with greyish-brown fur, black marks on its face, and a thick striped tail.","review":{"fact_id":"39c7b75e-8b76-4026-a914-24dee469b363","confidence":1,"verdict":"pass"}},{"lemma":"ape","sense_id":"4d49f41d-0745-4ea2-b5af-726b667e3fb2","gloss":"A large animal like a monkey with no tail, such as a gorilla or chimpanzee.","review":{"fact_id":"7de927fc-c6d6-47fb-8cf7-e916b495fe45","confidence":1,"verdict":"pass"}},{"lemma":"spider","sense_id":"ab01e3c8-8afb-4ded-8ccc-8aba859c74e2","gloss":"A small creature with eight thin legs that spins webs to catch insects for food.","review":{"fact_id":"20e324c4-7907-4317-8acd-3a1a7feaff1c","confidence":1,"verdict":"pass"}},{"lemma":"snail","sense_id":"29e51f39-19fc-4872-bbef-2fde26efbfdd","gloss":"A small soft creature with a hard round shell on its back that moves very slowly.","review":{"fact_id":"dc5ffc3f-4d3f-4d49-9745-ab36108268c8","confidence":1,"verdict":"pass"}},{"lemma":"octopus","sense_id":"88cc7f19-cfe5-4ddb-9066-422ffa0e3efa","gloss":"A sea creature with a soft round body and eight long arms.","review":{"fact_id":"9bae48a3-ee1e-47d2-860b-1389e01d2581","confidence":1,"verdict":"pass"}},{"lemma":"crab","sense_id":"eaaefa17-bd69-4147-8c3f-e50f8c393fb8","gloss":"A sea creature with a hard shell, eight legs, and two large claws, that moves sideways.","review":{"fact_id":"5be1ceb5-28f5-4dfd-908a-90c60aabf483","confidence":1,"verdict":"pass"}},{"lemma":"lobster","sense_id":"cfc9e528-c844-4acd-8a68-7947e163cce9","gloss":"A sea creature with a hard shell, a long body, and two large claws.","review":{"fact_id":"71f3ba71-1bdc-4079-8074-029a002b2c92","confidence":1,"verdict":"pass"}},{"lemma":"caterpillar","sense_id":"86de6123-a80f-41ca-aa05-ae917f8b1c71","gloss":"A small creature like a worm with legs that develops into a butterfly or moth.","review":{"fact_id":"943930e3-dd8a-4e68-848d-2b7d62506456","confidence":1,"verdict":"pass"}},{"lemma":"amphibian","sense_id":"05beedb8-d816-4def-b624-aa878d0ce269","gloss":"A cold-blooded vertebrate such as a frog, toad, or salamander, typically developing from an aquatic larva into an air-breathing adult.","review":{"fact_id":"77a6b186-2661-460e-badc-a4bd159867be","confidence":1,"verdict":"pass"}},{"lemma":"predator","sense_id":"c91b473c-d4b2-476b-9c17-0b4e961ea8ea","gloss":"An animal that kills and eats other animals.","review":{"fact_id":"13afee36-a249-4457-b9b6-c4add8005f53","confidence":1,"verdict":"pass"}},{"lemma":"prey","sense_id":"e0fe6fd0-b54e-46d3-82a4-fc91d727399b","gloss":"An animal that is hunted and killed by another animal for food.","review":{"fact_id":"6458412c-1fd3-4987-b441-066f6e471722","confidence":1,"verdict":"pass"}}],"part_of":[],"parts":[{"lemma":"coat","sense_id":"b550a582-e465-4f07-bb5a-99c8599719d1","gloss":"The fur, hair, or wool covering an animal''s body.","review":{"fact_id":"b3994d7b-6fcd-405c-8003-d2b016525654","confidence":0.98,"verdict":"pass"}},{"lemma":"tail","sense_id":"e7672035-e72c-4084-b1dc-651200cc1ae9","gloss":"The rearward extension of an animal''s body beyond its trunk.","review":{"fact_id":"c06e72b2-db0e-48de-9d4f-04a00e3a7d7b","confidence":1,"verdict":"pass"}},{"lemma":"paw","sense_id":"37c927cc-2723-4f00-a115-e957b57094e8","gloss":"The foot of a four-legged mammal that has claws or nails.","review":{"fact_id":"bce14270-a16b-4d3a-8cad-9063729c0172","confidence":1,"verdict":"pass"}},{"lemma":"claw","sense_id":"0f236563-1f71-4977-9024-6c3e82b7c93d","gloss":"One of the sharp, curved nails on the foot of a bird or animal.","review":{"fact_id":"6571932c-8f92-4a26-8235-da896729ad14","confidence":1,"verdict":"pass"}}]},"review":{"gloss":{"fact_id":"ec525ec1-93dd-4211-9c54-1fe8a382ec20","confidence":1,"verdict":"pass"},"translations":{"zh":[{"fact_id":"9d33d3e5-896d-4534-afc1-7add68710ab3","confidence":1,"verdict":"pass"}]}}},{"id":"cbcbbe15-4e8b-4732-8707-49ace61b3c23","gloss":"Any living creature, including a human, as opposed to a plant.","labels":[],"region":null,"rare":false,"translations":{"zh":["动物（包括人类）"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"dc79062c-8ed9-4eb1-b204-c01e1482c958","confidence":0.88,"verdict":"pass"}},"examples":[{"text":"Unlike plants, animals cannot make their own food using sunlight.","translations":{"zh":"与植物不同，动物不能利用阳光自行制造食物。"},"review":{"fact_id":"1d535ad0-f3da-4352-9bd0-576f565451c2","confidence":0.99,"verdict":"pass"}},{"text":"Humans, jellyfish, and ants are all animals.","translations":{"zh":"人类、水母和蚂蚁都是动物。"},"review":{"fact_id":"9c563942-98cc-412c-8472-e65b6334d636","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"social animal","pattern":"adjective_noun","review":{"fact_id":"daa9ccae-40e9-426d-aa05-464f20937cff","confidence":0.96,"verdict":"pass"}},{"text":"marine animal","pattern":"adjective_noun","review":{"fact_id":"da7141a9-135a-420c-963a-6271b40d9844","confidence":0.91,"verdict":"pass"}}],"topics":[{"id":"biology","name":{"en":"Biology","zh":"生物"},"review":{"fact_id":"d9e3b1ba-bfd0-43b5-a3f8-3354ac24191c","confidence":0.99,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[{"lemma":"plant","sense_id":"887f479f-a247-44bd-a125-4fefe9d9b443","gloss":"A living organism such as a tree, shrub, or grass, typically growing in soil and making its food by photosynthesis.","review":{"fact_id":"9f26d9a5-ae97-4171-ad51-bff107491da1","confidence":1,"verdict":"pass"}}],"broader":[{"lemma":"organism","sense_id":"74226e2e-6167-4c8b-9035-e52d6dbd54ce","gloss":"An individual living thing.","review":{"fact_id":"9267d125-17ea-42a5-b814-274b1e328f47","confidence":0.94,"verdict":"pass"}}],"narrower":[],"part_of":[],"parts":[{"lemma":"head","sense_id":"dad944e2-3c0d-42a0-8809-50fe4f0512b6","gloss":"The part of the body above the neck that contains the brain, eyes, nose, and mouth.","review":{"fact_id":"18dc7fd7-52bd-48ea-9437-b64b0a958952","confidence":0.99,"verdict":"pass"}},{"lemma":"leg","sense_id":"af619435-7e6e-41f7-933e-50ef89136f4b","gloss":"A limb used for standing and walking.","review":{"fact_id":"a6bcb118-4f02-431f-9967-ca23cd08e99d","confidence":0.99,"verdict":"pass"}}]},"review":{"gloss":{"fact_id":"ca7393a2-37fa-45b4-8951-3a4d0c7b6538","confidence":1,"verdict":"pass"},"translations":{"zh":[{"fact_id":"c50b0dfe-56f9-416b-9529-712ea22ff0d2","confidence":1,"verdict":"pass"}]}}},{"id":"715cf83d-8d69-4f47-9251-5b81317e69f7","gloss":"A person who behaves in a cruel, violent, or uncivilized way.","labels":[],"region":null,"rare":false,"translations":{"zh":["畜生；野蛮残暴的人"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"cc8fd09c-71bf-4e6e-9dbd-fcf02723c250","confidence":0.93,"verdict":"pass"}},"examples":[{"text":"The prisoners described the guard who tortured them as an animal.","translations":{"zh":"囚犯们称那个折磨他们的看守是个畜生。"},"review":{"fact_id":"219b00e7-2364-4525-939d-c0ff05df2d2f","confidence":0.99,"verdict":"pass"}},{"text":"Anyone who could beat a defenseless child like that is an animal.","translations":{"zh":"能那样殴打一个毫无还手之力的孩子的人，简直是个畜生。"},"review":{"fact_id":"d6625354-f71f-4ba9-8d2a-858bc04dd928","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"behave like an animal","pattern":"phrase","review":{"fact_id":"d2275c22-69a3-4334-9dcd-942fd462a871","confidence":0.91,"verdict":"pass"}}],"topics":[{"id":"personality","name":{"en":"Personality","zh":"性格"},"review":{"fact_id":"0f0b3f56-ae3a-4e53-915f-e6f150a4f1ae","confidence":0.9,"verdict":"pass"}}],"relations":{"synonyms":[{"lemma":"brute","sense_id":"e30e863d-1a12-40f3-bbbb-381a4282791b","gloss":"A cruel, violent, or uncivilized person.","review":{"fact_id":"771b7048-0a97-4d37-8a06-a905be3aca90","confidence":0.96,"verdict":"pass"}}],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"31b04be6-c210-4ef3-9fce-95268f470b45","confidence":0.86,"verdict":"pass"},"translations":{"zh":[{"fact_id":"eab49ec3-3442-4477-8b97-646df7bd0380","confidence":0.99,"verdict":"pass"}]}}},{"id":"9f7d682a-d218-4bd4-961c-9689d44c22b3","gloss":"A person or thing of a particular type.","labels":["informal"],"region":null,"rare":false,"translations":{"zh":["某一类型的人或事物"]},"grammar":{"countability":"countable","patterns":[],"prepositions":[],"review":{"fact_id":"7d1a4c0d-f811-410c-a381-2f746c7a62bd","confidence":0.92,"verdict":"pass"}},"examples":[{"text":"Running a large company is a very different animal from managing a small shop.","translations":{"zh":"经营一家大公司与管理一家小店完全是两码事。"},"review":{"fact_id":"7aceea50-81be-47d9-aa42-2ffe1d9cd642","confidence":0.99,"verdict":"pass"}},{"text":"She is a political animal who loves campaigning and debating.","translations":{"zh":"她是个热衷政治的人，喜欢参加竞选活动和辩论。"},"review":{"fact_id":"d3a08b6e-fe92-4135-b110-033d9a905ff2","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"a different animal","pattern":"phrase","review":{"fact_id":"4166c340-2037-494d-bc2c-8daa57484e18","confidence":0.97,"verdict":"pass"}},{"text":"political animal","pattern":"adjective_noun","review":{"fact_id":"c30afd5a-d584-4707-83d7-92d6330c82a6","confidence":0.99,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[{"lemma":"beast","sense_id":"a689b2ce-9fce-4157-941b-9bc6fa56577a","gloss":"A person or thing of a particular kind.","review":{"fact_id":"72ba5f87-f880-49b7-bdc8-e6929e96cb77","confidence":0.82,"verdict":"pass"}}],"antonyms":[],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"5dec1a5a-6e16-42c2-a3bf-0631f546cc81","confidence":0.99,"verdict":"pass"},"translations":{"zh":[{"fact_id":"3c47b9eb-46ca-4291-8a7d-a964f5b035f9","confidence":0.99,"verdict":"pass"}]}}}],"review":{"forms":{"plural":[{"fact_id":"087e1c98-b350-492d-b499-979af9d62415","confidence":0.99,"verdict":"pass"}]}}},{"pos":"adjective","cefr":null,"pronunciations":[],"forms":{},"senses":[{"id":"ee2f1833-230d-4427-a60d-5e693f40e930","gloss":"Relating to animals or derived from animals.","labels":[],"region":null,"rare":false,"translations":{"zh":["动物的；动物来源的"]},"grammar":{"position":"attributive_only","patterns":[],"prepositions":[],"review":{"fact_id":"babc08bd-f0c9-4116-9ed4-ae25e93dd582","confidence":0.98,"verdict":"pass"}},"examples":[{"text":"The soap contains no animal fat.","translations":{"zh":"这种肥皂不含动物脂肪。"},"review":{"fact_id":"1ea01eab-a4ee-44b8-9002-9e1336ae7e69","confidence":0.99,"verdict":"pass"}},{"text":"She avoids eating animal products, including meat, milk, and eggs.","translations":{"zh":"她不吃肉、奶、蛋等动物性食品。"},"review":{"fact_id":"710da19d-7040-447a-ad43-369a8475f1ad","confidence":0.99,"verdict":"pass"}}],"collocations":[{"text":"animal products","pattern":"adjective_noun","review":{"fact_id":"76f5150b-417b-4efc-8de0-63973cba3138","confidence":0.97,"verdict":"pass"}},{"text":"animal welfare","pattern":"adjective_noun","review":{"fact_id":"ae29a65a-91ba-43ba-83f2-91ccd01345ff","confidence":0.96,"verdict":"pass"}},{"text":"animal fat","pattern":"adjective_noun","review":{"fact_id":"08c5c447-2361-44af-8112-e11e45f51863","confidence":0.98,"verdict":"pass"}}],"topics":[{"id":"biology","name":{"en":"Biology","zh":"生物"},"review":{"fact_id":"02792d78-f81b-4088-86fb-0ed52b029240","confidence":0.98,"verdict":"pass"}}],"relations":{"synonyms":[],"antonyms":[{"lemma":"vegetable","sense_id":"7ecb9620-e405-4245-a837-09d085785ef1","gloss":"Relating to plants or derived from plants.","review":{"fact_id":"77945971-9910-4683-8dd7-3aef3616f30a","confidence":0.88,"verdict":"pass"}}],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"733dd4b2-baa5-4272-ac75-db0a8cd5bbe5","confidence":0.92,"verdict":"pass"},"translations":{"zh":[{"fact_id":"ee679596-054f-488b-a65f-fbb3f506a222","confidence":0.99,"verdict":"pass"}]}}},{"id":"bdf88512-73ef-42f4-8639-bffa1020f37d","gloss":"Relating to physical appetites and instincts rather than reason or spiritual qualities.","labels":[],"region":null,"rare":false,"translations":{"zh":["肉体欲望的；本能的"]},"grammar":{"position":"attributive_only","patterns":[],"prepositions":[],"review":{"fact_id":"059bf872-69ed-43d4-a564-84777ee0fb55","confidence":0.97,"verdict":"pass"}},"examples":[{"text":"Hunger brought out their most basic animal instincts.","translations":{"zh":"饥饿激发了他们最原始的动物本能。"},"review":{"fact_id":"de2391bb-7849-4abd-a75c-6eb1f86048c2","confidence":0.99,"verdict":"pass"}},{"text":"In his panic, animal instinct took over and he ran for his life.","translations":{"zh":"惊慌之中，本能占了上风，他拼命逃跑。"},"review":{"fact_id":"b8ce65e9-e79d-4f2a-a207-07c51f768a40","confidence":0.95,"verdict":"pass"}}],"collocations":[{"text":"animal instincts","pattern":"adjective_noun","review":{"fact_id":"de33f1e4-3ed0-41d9-b1e5-05c574e3dd58","confidence":0.98,"verdict":"pass"}},{"text":"animal passions","pattern":"adjective_noun","review":{"fact_id":"0caebfb7-df30-4af6-9071-96e57b38b660","confidence":0.96,"verdict":"pass"}},{"text":"animal appetites","pattern":"adjective_noun","review":{"fact_id":"fbddb0b5-6e22-45cd-9f0c-323888408290","confidence":0.96,"verdict":"pass"}}],"topics":[],"relations":{"synonyms":[{"lemma":"carnal","sense_id":"4ba87f13-83ad-402c-a664-adb4ab705adb","gloss":"Relating to physical appetites and pleasures rather than intellectual or spiritual concerns.","review":{"fact_id":"60370701-ce7d-4c1d-8756-904921480277","confidence":0.86,"verdict":"pass"}}],"antonyms":[{"lemma":"spiritual","sense_id":"ab6a8c6c-096c-42e8-ade1-7032437903db","gloss":"Relating to the soul or spirit rather than the body or material things.","review":{"fact_id":"ca840ea2-d8c0-4eb7-bcc3-0ccb6fcb54a4","confidence":0.86,"verdict":"pass"}}],"broader":[],"narrower":[],"part_of":[],"parts":[]},"review":{"gloss":{"fact_id":"825a2a3f-70b0-4bcd-a8a1-3a83a9ab2ea1","confidence":0.83,"verdict":"pass"},"translations":{"zh":[{"fact_id":"a582a152-2840-491e-a769-52fb83296c3a","confidence":0.95,"verdict":"pass"}]}}}],"review":{"forms":{}}}],"summary":{"lemma":"animal","pos":["noun","adjective"],"cefr":"A1","gloss":"A living creature that is not a plant or a human, such as a dog, bird, fish or insect.","translations":{"zh":"动物"}},"review":{"entry":{"fact_id":"3ff7b481-9ad6-4764-bb5f-24f008b4921b","confidence":0.99,"verdict":"pass"},"sense_list":{"fact_id":"81967c5a-7b03-4